import sys, json
sys.path.insert(0, '/tmp/odk44')
from data import C1, C2, C3, C4, C5, C6, C7, C8

CONV = {
    'nMs': lambda x: x / 1000.0,        # nM/s -> uM/s
    'nMmin': lambda x: x / 60000.0,     # nM/min -> uM/s
    'uMmin': lambda x: x / 60.0,        # uM/min -> uM/s
    'uMs': lambda x: x,                 # already uM/s
    'mAU': lambda x: x / (6.22 * 0.55 * 60.0),  # mAU/min -> uM/s (Beer-Lambert, header values)
}

def pts(rows, scale=1.0):
    return [(float(S), CONV[u](v) * scale) for (_, S, v, u) in rows]

def ssr(xs, ys, vmax, km):
    return sum((y - vmax * x / (km + x)) ** 2 for x, y in zip(xs, ys))

def fit_free(xs, ys):
    # For each Km, optimal Vmax is closed-form: sum(v*f)/sum(f^2), f = S/(Km+S)
    def best_v(km):
        f = [x / (km + x) for x in xs]
        return sum(y * fi for y, fi in zip(ys, f)) / sum(fi * fi for fi in f)
    def cost(lk):
        km = 10 ** lk
        return ssr(xs, ys, best_v(km), km)
    lo, hi = -1.0, 5.0
    # coarse grid then golden refinement
    grid = [lo + (hi - lo) * i / 2000 for i in range(2001)]
    lbest = min(grid, key=cost)
    a, b = lbest - 0.01, lbest + 0.01
    gr = (5 ** 0.5 - 1) / 2
    c, d = b - gr * (b - a), a + gr * (b - a)
    for _ in range(200):
        if cost(c) < cost(d): b = d
        else: a = c
        c, d = b - gr * (b - a), a + gr * (b - a)
    lk = (a + b) / 2
    km = 10 ** lk
    return best_v(km), km, cost(lk)

def fit_fixed_vmax(xs, ys, vmax):
    def cost(lk):
        return ssr(xs, ys, vmax, 10 ** lk)
    grid = [-1.0 + 6.0 * i / 4000 for i in range(4001)]
    lbest = min(grid, key=cost)
    a, b = lbest - 0.002, lbest + 0.002
    gr = (5 ** 0.5 - 1) / 2
    c, d = b - gr * (b - a), a + gr * (b - a)
    for _ in range(200):
        if cost(c) < cost(d): b = d
        else: a = c
        c, d = b - gr * (b - a), a + gr * (b - a)
    return 10 ** ((a + b) / 2)

sets = {'C1': pts(C1, 0.5), 'C2': pts(C2), 'C3': pts(C3), 'C4': pts(C4), 'C5': pts(C5),
        'C6': pts(C6), 'C7': pts(C7), 'C8': pts(C8)}
res = {}
for k in ['C1', 'C2', 'C3', 'C6', 'C8']:
    xs, ys = zip(*sets[k])
    vm, km, c = fit_free(xs, ys)
    res[k] = (vm, km)
    print(k, 'n=%d' % len(xs), 'Vmax=%.5f' % vm, 'Km=%.3f' % km, 'SSR=%.3e' % c)
# inhibitor conditions: shared Vmax from matching no-inhibitor condition
for k, ref in [('C4', 'C8'), ('C5', 'C8'), ('C7', 'C1')]:
    xs, ys = zip(*sets[k])
    vm = res[ref][0]
    km = fit_fixed_vmax(xs, ys, vm)
    res[k] = (vm, km)
    print(k, 'n=%d' % len(xs), 'Vmax(fixed from %s)=%.5f' % (ref, vm), 'Km_app=%.3f' % km)
json.dump({k: list(v) for k, v in res.items()}, open('/tmp/odk44/res.json', 'w'), indent=1)

import sys
sys.path.insert(0, '/tmp/odk44')
from data import C1, C2, C3, C4, C5, C6, C7, C8
from fit import CONV, res
conds = {'C1': C1, 'C2': C2, 'C3': C3, 'C4': C4, 'C5': C5, 'C6': C6, 'C7': C7, 'C8': C8}
for k, rows in conds.items():
    vm, km = res[k]
    scale = 0.5 if k == 'C1' else 1.0
    for (s, S, v, u) in rows:
        r = CONV[u](v) * scale / (vm * S / (km + S))
        if r < 0.85 or r > 1.12:
            print(k, s, S, u, round(r, 3))

